-- Isolated synthetic data; no real practice settings. Run through the disposable runner.
begin;
select extensions.plan(1);
do $$
declare
 owner_id uuid:=gen_random_uuid();doctor_id uuid:=gen_random_uuid();other_doctor uuid:=gen_random_uuid();outsider uuid:=gen_random_uuid();
 biz uuid;foreign_biz uuid;prof uuid;second_prof uuid;svc uuid;followup uuid;foreign_svc uuid;revision bigint;policy jsonb;quote jsonb;schema jsonb;payload jsonb;created record;
 base_month date:=date_trunc('month',now())::date;at_time timestamptz:=date_trunc('month',now())+interval '1 month 4 days 10 hours';
 request_id uuid:=gen_random_uuid();exception_key uuid:=gen_random_uuid();items jsonb;settings_time timestamptz;service_time timestamptz;appointment_time timestamptz;
 file public.patient_radiographs%rowtype;replay public.patient_radiographs%rowtype;second_file public.patient_radiographs%rowtype;third_file public.patient_radiographs%rowtype;budget jsonb;bytes_before bigint;reserved_before bigint;policy_row public.service_price_policies%rowtype;rounding_row public.service_price_policies%rowtype;
 before_name text;blocks_before integer;image record;unused_path text;cleanup_items jsonb;
begin
 insert into auth.users(id,email) values(owner_id,'extension-owner@example.test'),(doctor_id,'extension-doctor@example.test'),(other_doctor,'extension-second@example.test'),(outsider,'extension-other@example.test');
 insert into public.businesses(name,slug,industry,timezone,patient_documents_enabled,max_booking_days_ahead) values('Consultorio sintético extensiones','ext-'||gen_random_uuid(),'other','UTC',true,90) returning id into biz;
 insert into public.businesses(name,slug,industry,timezone) values('Otro consultorio sintético','ext-other-'||gen_random_uuid(),'other','UTC') returning id into foreign_biz;
 insert into public.business_users(business_id,user_id,role,status,accepted_at) values(biz,owner_id,'owner','active',now()),(biz,doctor_id,'professional','active',now()),(biz,other_doctor,'professional','active',now()),(foreign_biz,outsider,'owner','active',now());
 update public.business_subscriptions set commercial_access_enabled=true,is_permanent=true,subscription_status='active',paid_until=null,grace_until=null,restricted_until=null where business_id in (biz,foreign_biz);
 insert into public.professionals(business_id,name) values(biz,'Profesional sintética') returning id into prof;
 insert into public.professionals(business_id,name) values(biz,'Segunda profesional sintética') returning id into second_prof;
 insert into public.professional_users(business_id,professional_id,user_id) values(biz,prof,doctor_id),(biz,second_prof,other_doctor);
 insert into public.services(business_id,name,duration_minutes) values(biz,'Primera consulta sintética',30) returning id into svc;
 insert into public.services(business_id,name,duration_minutes) values(biz,'Control sintético',30) returning id into followup;
 insert into public.services(business_id,name,duration_minutes) values(foreign_biz,'Prestación ajena',30) returning id into foreign_svc;
 insert into public.professional_services(business_id,professional_id,service_id) values(biz,prof,svc),(biz,prof,followup),(biz,second_prof,svc);
 insert into public.availability_rules(business_id,professional_id,weekday,start_time,end_time,slot_interval_minutes,break_minutes) select biz,prof,n,'09:00','19:00',30,0 from generate_series(0,6)n;
 perform set_config('request.jwt.claim.sub',owner_id::text,true);perform set_config('request.jwt.claim.role','authenticated',true);
 policy:=jsonb_build_object('base_amount',20000,'currency','ARS','base_month',base_month,'first_adjustment_month',base_month+interval '1 month','monthly_percentage',2,'rounding_unit',1,'adjustments',jsonb_build_array(jsonb_build_object('month',base_month+interval '3 months','kind','override','percentage',1),jsonb_build_object('month',base_month+interval '4 months','kind','override','percentage',0)));
 perform public.save_service_price_policy(biz,svc,prof,0,policy);
 select * into policy_row from public.service_price_policies where business_id=biz and service_id=svc and professional_id=prof;
 if private.calculate_policy_monthly_amount(policy_row,(base_month+interval '1 month')::date)<>20400 or private.calculate_policy_monthly_amount(policy_row,(base_month+interval '2 months')::date)<>20808 or private.calculate_policy_monthly_amount(policy_row,(base_month+interval '3 months')::date)<>21016 or private.calculate_policy_monthly_amount(policy_row,(base_month+interval '4 months')::date)<>21016 then raise exception 'FAIL_MONTHLY_COMPOUND_OR_OVERRIDES';end if;
 rounding_row:=policy_row;rounding_row.id:=gen_random_uuid();rounding_row.base_amount:=1000;rounding_row.rounding_unit:=100;
 if private.calculate_policy_monthly_amount(rounding_row,(base_month+interval '3 months')::date)<>1100 then raise exception 'FAIL_ROUNDING_CHAINED_MONTHLY';end if;
 begin perform public.save_service_price_policy(biz,svc,prof,0,policy);raise exception 'FAIL_PRICE_STALE_REVISION';exception when others then if sqlerrm<>'PRICE_POLICY_CHANGED' then raise;end if;end;
 begin perform public.save_service_price_policy(biz,svc,prof,1,policy||'{"base_amount":20.001}');raise exception 'FAIL_PRICE_PRECISION';exception when others then if sqlerrm<>'PRICE_CONFIGURATION_INVALID' then raise;end if;end;
 perform set_config('request.jwt.claim.sub',doctor_id::text,true);
 begin perform public.save_service_price_policy(biz,svc,second_prof,0,policy);raise exception 'FAIL_PRICE_OTHER_PROFESSIONAL';exception when others then if sqlerrm<>'PRICE_ACCESS_DENIED' then raise;end if;end;
 perform set_config('request.jwt.claim.sub',outsider::text,true);
 begin perform public.save_service_price_policy(biz,svc,prof,1,policy);raise exception 'FAIL_PRICE_OTHER_BUSINESS';exception when others then if sqlerrm<>'PRICE_ACCESS_DENIED' then raise;end if;end;
 perform set_config('request.jwt.claim.sub',owner_id::text,true);
 quote:=public.get_public_service_price_quote(biz,svc,array[prof],at_time::date);
 if quote->>'amount'<>'20400' or quote->>'adjusted'<>'true' or length(quote->>'hash')<>64 then raise exception 'FAIL_QUOTE:%',quote;end if;
 perform public.save_service_price_policy(biz,svc,null,0,policy||'{"base_amount":30000}');
 if (public.get_public_service_price_quote(biz,svc,array[prof,second_prof],at_time::date)->>'amount')<>'30600' then raise exception 'FAIL_EXPLICIT_TEAM_PRICE';end if;
 if (public.get_public_service_price_quote(biz,svc,array[prof],at_time::date)->>'amount')<>'20400' then raise exception 'FAIL_INDIVIDUAL_PRICE_PRECEDENCE';end if;
 perform set_config('request.jwt.claim.sub',doctor_id::text,true);execute 'set local role authenticated';
 if (select count(*) from public.service_price_policies where business_id=biz and service_id=svc)<>2 then raise exception 'FAIL_PROFESSIONAL_SHARED_PRICE_READ';end if;
 begin perform public.save_service_price_policy(biz,svc,null,1,policy);raise exception 'FAIL_PROFESSIONAL_SHARED_PRICE_WRITE';exception when others then if sqlerrm<>'PRICE_ACCESS_DENIED' then raise;end if;end;
 execute 'reset role';perform set_config('request.jwt.claim.sub',owner_id::text,true);
 schema:=public.get_public_patient_booking_schema(biz,array[prof]);
 payload:=jsonb_build_object('business_id',biz,'professional_ids',array[prof],'patient_name','Ana Pérez Sintética','patient_phone_raw','3425048209','patient_phone_e164','+5493425048209','service_id',svc,'starts_at',at_time,'request_key',request_id,'schema_hash',schema->>'hash','answers','{}'::jsonb,'phone_status','valid','price_quote_hash',quote->>'hash');
 begin perform * from public.create_public_booking_with_information(payload||'{"price_quote_hash":"stale"}');raise exception 'FAIL_QUOTE_BYPASS';exception when others then if sqlerrm<>'PRICE_QUOTE_CHANGED' then raise;end if;end;
 if exists(select 1 from public.patients where business_id=biz) then raise exception 'FAIL_PRICE_REJECT_NOT_ATOMIC';end if;
 select * into created from public.create_public_booking_with_information(payload);
 if (select price_quote_snapshot->>'hash' from public.appointments where id=created.id)<>quote->>'hash' then raise exception 'FAIL_PRICE_NOT_SNAPSHOTTED';end if;
 perform public.save_service_price_policy(biz,svc,prof,1,policy||'{"monthly_percentage":3}');
 if (select price_quote_snapshot->>'amount' from public.appointments where id=created.id)<>'20400' then raise exception 'FAIL_PRICE_RETROACTIVE';end if;
 select booking_availability_revision into revision from public.businesses where id=biz;
 perform public.replace_professional_schedule_blocks(biz,prof,revision,jsonb_build_array(jsonb_build_object('weekdays',jsonb_build_array(extract(dow from at_time)::integer),'ranges','[{"start":"09:00","end":"17:00"}]'::jsonb,'slot_interval_minutes',30,'break_minutes',0,'service_scope','all'),jsonb_build_object('weekdays',jsonb_build_array(extract(dow from at_time)::integer),'ranges','[{"start":"17:00","end":"19:00"}]'::jsonb,'slot_interval_minutes',30,'break_minutes',0,'service_scope','restricted','service_ids',array[followup])));
 perform private.assert_service_schedule(biz,prof,followup,date_trunc('day',at_time)+interval '17 hours',date_trunc('day',at_time)+interval '17 hours 30 minutes');
 begin perform private.assert_service_schedule(biz,prof,svc,date_trunc('day',at_time)+interval '17 hours',date_trunc('day',at_time)+interval '17 hours 30 minutes');raise exception 'FAIL_RESTRICTED_SERVICE';exception when others then if sqlerrm<>'SCHEDULE_SERVICE_UNAVAILABLE' then raise;end if;end;
 begin perform * from public.create_appointment_with_patient_identity(biz,'existing',created.patient_id,null,'3425048209','+5493425048209',null,false,null,svc,array[prof],date_trunc('day',at_time)+interval '17 hours',null,owner_id,false,'manual','valid',false,gen_random_uuid()::text,false);raise exception 'FAIL_MANUAL_RESTRICTION_BYPASS';exception when others then if sqlerrm<>'SCHEDULE_SERVICE_UNAVAILABLE' then raise;end if;end;
 select booking_availability_revision into revision from public.businesses where id=biz;
 select name into before_name from public.professionals where id=prof;select count(*) into blocks_before from public.availability_rules where professional_id=prof;
 begin perform public.save_professional_editor(biz,prof,revision,jsonb_build_object('name','No debe persistir','is_public',true),null,'[]',gen_random_uuid(),'[{"type":"nonsense"}]',false);raise exception 'FAIL_SAVE_ALL_PARTIAL';exception when others then if sqlerrm='FAIL_SAVE_ALL_PARTIAL' then raise;end if;end;
 if (select name from public.professionals where id=prof)<>before_name or (select count(*) from public.availability_rules where professional_id=prof)<>blocks_before then raise exception 'FAIL_SAVE_ALL_ROLLBACK';end if;
 items:=jsonb_build_array(jsonb_build_object('professional_id',prof,'type','blocked','starts_at',date_trunc('day',at_time)+interval '1 day','ends_at',date_trunc('day',at_time)+interval '2 days','reason','Feriado sintético'),jsonb_build_object('professional_id',prof,'type','blocked','starts_at',date_trunc('day',at_time)+interval '3 days','ends_at',date_trunc('day',at_time)+interval '4 days','reason','Ausencia sintética'));
 perform public.create_availability_exception_batch(biz,revision,exception_key,items,false);
 perform public.create_availability_exception_batch(biz,revision,exception_key,items,false);
 if (select count(*) from public.availability_exceptions where business_id=biz)<>2 then raise exception 'FAIL_EXCEPTION_BATCH_REPLAY';end if;
 select booking_availability_revision into revision from public.businesses where id=biz;
 begin perform public.create_availability_exception_batch(biz,revision,gen_random_uuid(),jsonb_build_array(jsonb_build_object('professional_id',prof,'type','blocked','starts_at',date_trunc('day',at_time),'ends_at',date_trunc('day',at_time)+interval '1 day')),false);raise exception 'FAIL_EXISTING_APPOINTMENT_WARNING';exception when others then if sqlerrm<>'SCHEDULE_EXISTING_APPOINTMENTS' then raise;end if;end;
 select booking_availability_revision into revision from public.businesses where id=biz;
 perform public.create_availability_exception_batch(biz,revision,gen_random_uuid(),jsonb_build_array(jsonb_build_object('professional_id',prof,'type','blocked','starts_at',date_trunc('day',at_time),'ends_at',date_trunc('day',at_time)+interval '1 day')),true);
 update public.appointments set status='confirmed' where id=created.id;
 if not exists(select 1 from public.appointments where id=created.id and status='confirmed') then raise exception 'FAIL_BLOCK_AFFECTS_EXISTING_CONFIRMATION';end if;
 update public.appointments set status='cancelled' where id=created.id;
 begin update public.appointments set status='reserved' where id=created.id;raise exception 'FAIL_REACTIVATION_BYPASSES_BLOCK';exception when others then if sqlerrm<>'SCHEDULE_BLOCKED' then raise;end if;end;
 delete from public.availability_exceptions where business_id=biz and starts_at=date_trunc('day',at_time) and ends_at=date_trunc('day',at_time)+interval '1 day';
 update public.appointments set status='reserved' where id=created.id;
 delete from public.services where id=followup;
 begin perform private.assert_service_schedule(biz,prof,svc,date_trunc('day',at_time)+interval '17 hours',date_trunc('day',at_time)+interval '17 hours 30 minutes');raise exception 'FAIL_DELETED_SERVICE_OPENS_RULE';exception when others then if sqlerrm<>'SCHEDULE_SERVICE_UNAVAILABLE' then raise;end if;end;
 select updated_at into service_time from public.services where id=svc;
 perform public.save_service_patient_instructions(biz,svc,E'Indicaciones\nprivadas de prueba','Aviso público sintético',service_time);
 select updated_at into appointment_time from public.appointments where id=created.id;
 perform public.save_appointment_patient_instructions(biz,created.id,appointment_time,'Indicación específica','Descripción específica');
 if (select patient_instructions_snapshot from public.appointments where id=created.id)<>'Indicación específica' then raise exception 'FAIL_CARE_OVERRIDE';end if;
 begin perform public.save_appointment_patient_instructions(biz,created.id,appointment_time,'No debe persistir',null);raise exception 'FAIL_CARE_STALE';exception when others then if sqlerrm<>'CARE_CONFIGURATION_CHANGED' then raise;end if;end;
 select updated_at into settings_time from public.businesses where id=biz;
 perform public.save_public_practice_settings(biz,'{"patient_documents_enabled":true,"public_contact_enabled":true,"whatsapp_contact_enabled":true,"whatsapp_phone":"+5491112345678"}',settings_time);
 if (select whatsapp_enabled from public.businesses where id=biz) then raise exception 'FAIL_CONTACT_ACTIVATES_AUTOMATED_WHATSAPP';end if;
 perform set_config('request.jwt.claim.role','service_role',true);
 file:=public.begin_public_patient_document_upload(created.confirmation_token,gen_random_uuid(),'estudio.pdf','application/pdf',3500000,repeat('a',64));
 replay:=public.begin_public_patient_document_upload(created.confirmation_token,file.client_request_id,'estudio.pdf','application/pdf',3500000,repeat('a',64));
 if file.id<>replay.id or file.thumbnail_path is not null or file.source<>'patient' then raise exception 'FAIL_PATIENT_UPLOAD_REPLAY_OR_PDF';end if;
 if (select reserved_bytes from public.clinical_storage_budget where singleton)<>5000000 then raise exception 'FAIL_UPLOAD_NOT_PESSIMISTICALLY_RESERVED';end if;
 insert into storage.objects(bucket_id,name,metadata) values(file.storage_bucket,file.storage_path,'{"size":3500000,"mimetype":"application/pdf"}');
 perform public.complete_public_patient_document_upload(created.confirmation_token,file.id,3500000,'application/pdf');
 if not exists(select 1 from public.patient_radiographs where id=file.id and status='ready') then raise exception 'FAIL_PATIENT_DOC_NOT_READY';end if;
 begin perform public.get_public_patient_document_upload(repeat('0',64),file.id);raise exception 'FAIL_OTHER_TOKEN_DOC';exception when others then if sqlerrm<>'BOOKING_INFORMATION_UNAVAILABLE' then raise;end if;end;
 insert into public.professional_patient_links(business_id,professional_id,patient_id,source,is_active,created_by) values(biz,second_prof,created.patient_id,'manual',true,owner_id);
 perform public.grant_patient_radiograph_original_access(doctor_id,biz,created.patient_id,file.id);
 begin perform public.grant_patient_radiograph_original_access(other_doctor,biz,created.patient_id,file.id);raise exception 'FAIL_OTHER_PROFESSIONAL_PATIENT_DOC';exception when others then if sqlerrm<>'RADIOGRAPH_ACCESS_DENIED' then raise;end if;end;
 second_file:=public.begin_public_patient_document_upload(created.confirmation_token,gen_random_uuid(),'segunda.pdf','application/pdf',3500000,repeat('b',64));
 if (select used_bytes+reserved_bytes from public.clinical_storage_budget where singleton)<>8500000 then raise exception 'FAIL_ACTUAL_PLUS_PENDING_BUDGET';end if;
 insert into storage.objects(bucket_id,name,metadata) values(second_file.storage_bucket,second_file.storage_path,'{"size":3500000,"mimetype":"application/pdf"}');
 third_file:=public.begin_public_patient_document_upload(created.confirmation_token,gen_random_uuid(),'tercera.pdf','application/pdf',200000,repeat('c',64));
 begin insert into storage.objects(bucket_id,name,metadata) values(third_file.storage_bucket,third_file.storage_path,'{"size":5000000,"mimetype":"application/pdf"}');raise exception 'FAIL_PATIENT_ACTUAL_QUOTA';exception when others then if sqlerrm<>'CLINICAL_PATIENT_QUOTA' then raise;end if;end;
 insert into storage.objects(bucket_id,name,metadata) values(third_file.storage_bucket,third_file.storage_path,'{"size":200000,"mimetype":"application/pdf"}');
 delete from public.clinical_upload_slots where file_id=third_file.id;
 begin update storage.objects set metadata=metadata||'{"size":5000000}' where bucket_id=third_file.storage_bucket and name=third_file.storage_path;raise exception 'FAIL_EXPIRED_SLOT_BYPASSES_PATIENT_QUOTA';exception when others then if sqlerrm<>'CLINICAL_PATIENT_QUOTA' then raise;end if;end;
 begin update storage.objects set metadata=metadata||jsonb_build_object('untrusted',repeat('x',5000)) where bucket_id=third_file.storage_bucket and name=third_file.storage_path;raise exception 'FAIL_LARGE_OBJECT_METADATA';exception when others then if sqlerrm<>'CLINICAL_DOCUMENT_METADATA_TOO_LARGE' then raise;end if;end;
 if (select used_bytes from public.clinical_storage_budget where singleton)<>7200000 then raise exception 'FAIL_THIRD_SMALL_FILE_BLOCKED';end if;
 begin perform public.begin_public_patient_document_upload(created.confirmation_token,gen_random_uuid(),'cuarta.pdf','application/pdf',1,repeat('c',64));raise exception 'FAIL_PATIENT_DOCUMENT_COUNT';exception when others then if sqlerrm<>'CLINICAL_PATIENT_QUOTA' then raise;end if;end;
 if (select count(*) from public.patient_radiographs where appointment_id=created.id)<>3 then raise exception 'FAIL_QUOTA_REJECT_PERSISTED_METADATA';end if;
 select used_bytes,reserved_bytes into bytes_before,reserved_before from public.clinical_storage_budget where singleton;
 update public.clinical_storage_budget set max_bytes=used_bytes+reserved_bytes;
 begin perform public.begin_patient_radiograph_upload(owner_id,biz,created.patient_id,gen_random_uuid(),'prof.pdf','application/pdf',100,repeat('d',64));raise exception 'FAIL_GLOBAL_BUDGET';exception when others then if sqlerrm<>'CLINICAL_STORAGE_QUOTA' then raise;end if;end;
 if (select used_bytes from public.clinical_storage_budget where singleton)<>bytes_before or (select reserved_bytes from public.clinical_storage_budget where singleton)<>reserved_before then raise exception 'FAIL_GLOBAL_BUDGET_ROLLBACK';end if;
 update public.clinical_storage_budget set max_bytes=700000000;
 select * into image from public.begin_patient_radiograph_upload(owner_id,biz,created.patient_id,gen_random_uuid(),'imagen.jpg','image/jpeg',100,repeat('d',64));
 unused_path:=image.thumbnail_path;
 insert into storage.objects(bucket_id,name,metadata) values(image.storage_bucket,image.storage_path,'{"size":100,"mimetype":"image/jpeg"}'),(image.storage_bucket,unused_path,'{"size":50,"mimetype":"image/jpeg"}');
 perform public.complete_patient_radiograph_upload(owner_id,biz,created.patient_id,image.radiograph_id,100,'image/jpeg',false);
 update public.clinical_upload_slots set expires_at=clock_timestamp()-interval '1 minute' where file_id=image.radiograph_id;
 -- Starting an unrelated upload must not erase the reference needed to clean the unused preview.
 perform public.begin_patient_radiograph_upload(owner_id,biz,created.patient_id,gen_random_uuid(),'otra.pdf','application/pdf',100,repeat('e',64));
 cleanup_items:=public.claim_expired_clinical_uploads(biz,owner_id);
 if not exists(select 1 from jsonb_array_elements(cleanup_items) item where item->>'id'=image.radiograph_id::text and item->'paths'=jsonb_build_array(unused_path)) then raise exception 'FAIL_UNUSED_PREVIEW_CLEANUP';end if;
 if not exists(select 1 from public.patient_radiographs where id=image.radiograph_id and status='ready') or not exists(select 1 from storage.objects where bucket_id=image.storage_bucket and name=image.storage_path) then raise exception 'FAIL_CLEANUP_CONFIRMED_ORIGINAL';end if;
 perform set_config('request.jwt.claim.role','authenticated',true);perform set_config('request.jwt.claim.sub',other_doctor::text,true);execute 'set local role authenticated';
 if exists(select 1 from public.patient_radiographs where id=file.id) then raise exception 'FAIL_DOC_SCOPE_RLS';end if;execute 'reset role';
 if has_function_privilege('anon','public.begin_public_patient_document_upload(text,uuid,text,text,bigint,text,text)','execute') or has_function_privilege('authenticated','public.complete_public_patient_document_upload(text,uuid,bigint,text)','execute') or has_table_privilege('authenticated','public.clinical_storage_budget','update') then raise exception 'FAIL_UPLOAD_UNSAFE_GRANTS';end if;
end $$;
select extensions.pass('Monthly pricing, snapshots, tenant permissions, restricted schedules, atomic editor, exception replay, clinical quotas and limited patient capability');
select * from extensions.finish();
rollback;
